-- 확인: 남은 줄표 개수 (0이어야 함. 코드 블록 안 기호는 제외 안 되므로 아래는 참고용)
SELECT id,
       (length(title_ko)   - length(replace(title_ko,   '—', ''))) AS title_ko_dash,
       (length(title_en)   - length(replace(title_en,   '—', ''))) AS title_en_dash,
       (length(content_ko) - length(replace(content_ko, '—', ''))) AS content_ko_dash,
       (length(content_en) - length(replace(content_en, '—', ''))) AS content_en_dash
FROM blog_posts
ORDER BY date DESC;
